Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module RlLia.
Import Ltac2.Ltac2 Ltac2.Constr.

Ltac2 rec rl_has (l : constr) (c : constr) : bool :=
  if Constr.equal c l then true else
  let r := Ref.ref false in
  Constr.Unsafe.iter (fun x => if Ref.get r then () else if rl_has l x then Ref.set r true else ()) c;
  Ref.get r.

Ltac2 rl_is_arith (b : binder) : bool :=
  match Constr.Binder.name b with
  | Some id => String.equal (Ident.to_string id) "__arith"
  | None => false
  end.

Ltac2 rec rl_fix (lits : constr list) (hs : evar list ref) (c : constr) : constr :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.LetIn b _ body =>
    let t := Constr.Binder.type b in
    if Bool.and (rl_is_arith b) (Bool.and (Constr.Unsafe.is_closed t) (List.exist (fun l => rl_has l t) lits)) then
      let h := open_constr:(_ : $t) in
      let h := match Constr.Unsafe.kind h with Constr.Unsafe.Cast h' _ _ => h' | _ => h end in
      (match Constr.Unsafe.kind h with
       | Constr.Unsafe.Evar e _ => Ref.set hs (e :: Ref.get hs)
       | _ => Control.throw (Tactic_failure (Some (Message.of_string "RlLia: hole")))
       end);
      Constr.Unsafe.make (Constr.Unsafe.LetIn b h (rl_fix lits hs body))
    else Constr.Unsafe.map (rl_fix lits hs) c
  | _ => Constr.Unsafe.map (rl_fix lits hs) c
  end.

Ltac2 run1 (tab : string) (secs : string list) (s : string) (lits : constr list) : unit :=
  KReplay.kr_revert ();
  let ph := Ref.ref [] in
  let c := KReplay.decode_ph (Some ph) tab (KReplay.kr_secs secs) s in
  let hs := Ref.ref [] in
  let c := rl_fix lits hs c in
  Std.exact_no_check c;
  List.iter (fun (e, b) => Control.new_goal e; Control.enter (fun () => Std.exact_no_check (rl_fix lits hs b))) (Ref.get ph);
  List.iter (fun e => Control.new_goal e; Control.enter (fun () => ltac1:(intros; lia))) (Ref.get hs).
End RlLia.


Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

Section Segs.
Context {fx : FPState}.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Definition RLF (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (getr regs 21)))
    (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (getr regs 22)))
    (Z_to_bv 64 (s - 72)) (word_to_le_bytes 8 (getr regs 23)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (getr regs 24)))
    (Z_to_bv 64 (s - 88)) (word_to_le_bytes 8 (getr regs 25)))
    (Z_to_bv 64 (s - 96)) (word_to_le_bytes 8 (getr regs 26)))
    (Z_to_bv 64 (s - 104)) (word_to_le_bytes 8 (getr regs 27)).

Lemma rdn_RLF_above : forall m s ret regs (a : Z) (n : nat), (112 <= s)%Z -> (s <= a)%Z -> (a + Z.of_nat n < 2 ^ 64)%Z ->
