    /\ (1 <= nfw -> getr regs' 28 = Z_to_bv 64 (4 * nfw))%Z
    /\ regs_agree (fun r => In r [5; 8; 10; 11; 16; 17; 21; 28; 29; 30; 31]%list) regs regs'.
